static short mod3(short a)
{
    int r = a & 0xffff;
    r = (r >>> 8) + (r & 0xff);
    r = (r >>> 4) + (r & 0x0f);
    r = (r >>> 2) + (r & 0x03);
    r = (r >>> 2) + (r & 0x03);

    int t = r - 3;
    int c = t >> 31;

    return (short)((c & r) ^ (~c & t));
}

static byte mod3(byte a)
{
    return (byte)mod3((short)(a & 0xff));
}

